WITH parsed AS (SELECT id, customer_id, created_at, ship_to, attributes, FORALL(items, x -> x.qty <= 5) AS all_small_qty, attributes['utm_source'] AS utm_source, ship_to.zip AS ship_zip FROM carts) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, MAX(created_at) AS ended_at, COUNT(DISTINCT id) AS distinct_ids, MIN(created_at) AS first_created_at FROM parsed GROUP BY DATE_TRUNC('HOUR', created_at) ORDER BY distinct_ids NULLS LAST
